            item.fraction = 1.0
            total_profit += item.value
            remaining_capacity -= item.weight
        else:
            item.fraction = remaining_capacity / item.weight
            total_profit += item.value * item.fraction
            remaining_capacity = 0
            break
            
    return total_profit

